/**
 * Cross-language parity: this package must agree with the Python one.
 *
 * Both READMEs tell the reader that "a string prepared on either side of a
 * project is byte-identical". Until 2026-09-10 nothing enforced that, and it
 * was false: the two packages disagreed on five inputs, because the Python side
 * used str.lstrip() - which strips every Unicode space - where this side spells
 * out a narrow class of leading whitespace.
 *
 * parity_fixture.json is generated by tervatrix-rtl's
 * tools/build_parity_fixture.py, which runs BOTH implementations and refuses to
 * write anything while they disagree. The same file is committed to both
 * repositories, so a drift in either language fails a test here or there rather
 * than being absorbed the next time the fixture is regenerated.
 *
 * Keep this file and the fixture in step with tervatrix-rtl/tests/. They are
 * byte-identical copies on purpose.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

import { prepareRtl, isolateLtrRuns, stripBidi, forceRtlParagraphs, RLM } from '../src/index.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const { cases } = JSON.parse(readFileSync(join(HERE, 'parity_fixture.json'), 'utf8'));

const HEBREW = 'שלום';
// The codepoints that separate the two implementations' leading-whitespace
// classes. The first four are looked past when deciding whether a line already
// starts right to left; the last five are not.
const LOOKED_PAST = [0x0020, 0x0009, 0x000b, 0x000c, 0x000d, 0x00a0];
const NOT_LOOKED_PAST = [0x2000, 0x3000, 0x2009, 0x0085, 0x1680];

test('the parity fixture is present and populated', () => {
  assert.ok(cases.length >= 20, 'the parity fixture has lost cases');
});

test('the fixture still probes the whitespace boundary', () => {
  // A fixture that stopped carrying the awkward characters would pass for the
  // wrong reason, which is how the hand-maintained parity test missed the
  // divergence in the first place.
  const inputs = cases.map((c) => c.input);
  for (const cp of [...LOOKED_PAST.slice(2), ...NOT_LOOKED_PAST]) {
    assert.ok(
      inputs.some((text) => text.includes(String.fromCodePoint(cp))),
      `no case carries U+${cp.toString(16).toUpperCase().padStart(4, '0')} any more`,
    );
  }
});

test('prepareRtl matches the Python output', () => {
  for (const c of cases) {
    const actual = c.language === null ? prepareRtl(c.input) : prepareRtl(c.input, c.language);
    assert.equal(actual, c.prepare, c.name);
  }
});

test('isolateLtrRuns matches the Python output', () => {
  for (const c of cases) {
    assert.equal(isolateLtrRuns(c.input), c.isolate_runs, c.name);
  }
});

test('stripBidi matches the Python output', () => {
  for (const c of cases) {
    assert.equal(stripBidi(c.prepare), c.strip, c.name);
  }
});

test('the leading-whitespace class is the one Python now shares', () => {
  for (const cp of LOOKED_PAST) {
    const line = String.fromCodePoint(cp) + HEBREW;
    assert.equal(
      forceRtlParagraphs(line),
      line,
      `U+${cp.toString(16)} should be looked past, so no RTL mark`,
    );
  }
  for (const cp of NOT_LOOKED_PAST) {
    const line = String.fromCodePoint(cp) + HEBREW;
    assert.equal(
      forceRtlParagraphs(line),
      RLM + line,
      `U+${cp.toString(16)} is not in the class, so the line takes an RTL mark`,
    );
  }
});
